361	  async loadFolder(
362	    ipnsName: string,
363	    folderKey: Uint8Array,
364	    ipnsKeypair: { publicKey: Uint8Array; privateKey: Uint8Array }
365	  ): Promise<FolderState | null> {
366	    return this.withOperation('loadFolder', async () => {
367	      const result = await sdkCore.loadFolderMetadata({
368	        ipnsName,
369	        folderKey,
370	        ctx: this.ctx,
371	      });
372	
373	      if (!result) return null;
374	
375	      // IPNS reads lag a just-written sequence (#489 sequence-as-clock invariant).
376	      // Never overwrite a fresher in-memory entry with a stale IPNS snapshot.
377	      const existing = this.folderTree.get(ipnsName);
378	      if (existing && existing.sequenceNumber >= result.sequenceNumber) {
379	        this.emitter.emit({
380	          type: 'folder:loaded',
381	          folderId: ipnsName,
382	          ipnsName,
383	          children: existing.children,
384	          sequenceNumber: existing.sequenceNumber,
385	        });
386	        return existing;
387	      }
