413	  /**
414	   * Ensure a folder is present in the internal folderTree, self-bootstrapping
415	   * from root if necessary.
416	   *
417	   * If the target is already loaded, returns it immediately. Otherwise — when a
418	   * root IPNS keypair was configured — walks the folder tree from root (DFS with
419	   * early exit), resolving each folder's metadata and unwrapping each subfolder's
420	   * `folderKeyEncrypted` / `ipnsPrivateKeyEncrypted` with the vault keypair, until
421	   * the target is registered. Every folder visited along the way is cached, so
422	   * later calls are cheap.
423	   *
424	   * Returns null when the client cannot self-bootstrap (no `rootIpnsKeypair`
425	   * configured) or the target is not reachable from root. Callers fall back to
426	   * their existing 'Folder not loaded' error on null, so behavior is unchanged
427	   * when self-bootstrap is unavailable. This dissolves the "Folder not loaded"
428	   * failure class that previously required consumers to pre-seed folderTree
429	   * before every folderTree-dependent operation.
430	   *
431	   * @param targetIpnsName - IPNS name of the folder to ensure is loaded
432	   * @returns The loaded FolderState, or null if it cannot be bootstrapped
433	   * @internal
434	   */
435	  async ensureFolderLoaded(targetIpnsName: string): Promise<FolderState | null> {
436	    const existing = this.folderTree.get(targetIpnsName);
437	    if (existing) return existing;
438	
439	    // Cannot self-bootstrap without the root IPNS signing key.
440	    if (!this.internalRootIpnsKeypair) return null;
441	
442	    // 1. Ensure root is loaded. Root is special: it has no parent to unwrap its
443	    //    keys from, so they come from config (rootFolderKey + rootIpnsKeypair).
444	    const rootIpnsName = this.config.rootIpnsName;
445	    const root =
446	      this.folderTree.get(rootIpnsName) ??
447	      (await this.loadFolder(
448	        rootIpnsName,
449	        this.internalRootFolderKey,
450	        this.internalRootIpnsKeypair
451	      ));
452	    if (!root) return null;
453	    if (rootIpnsName === targetIpnsName) return root;
454	
455	    // 2. DFS from root, unwrapping child keys and loading metadata until the
456	    //    target is found. `visited` guards against repeats and pathological
457	    //    cycles in folder metadata.
458	    const visited = new Set<string>([rootIpnsName]);
459	    const stack: FolderState[] = [root];
460	    while (stack.length > 0) {
461	      const current = stack.pop() as FolderState;
462	      for (const child of current.children) {
463	        // type === 'folder' narrows child to FolderEntry (discriminated union).
464	        if (child.type !== 'folder') continue;
465	        if (visited.has(child.ipnsName)) continue;
466	        visited.add(child.ipnsName);
467	
468	        let childState = this.folderTree.get(child.ipnsName) ?? null;
469	        if (!childState) {
470	          try {
471	            // Unwrap this subfolder's keys with the vault keypair (ECIES), then
472	            // load its metadata. loadFolder adopts independent clones into the
473	            // folderTree (zeroed on destroy()); the transient unwrapped buffers
474	            // are left to GC, matching the existing loadFolder/registerFolder
475	            // paths which likewise don't eagerly zero their unwrapped inputs.
476	            const folderKey = await unwrapKey(
477	              hexToBytes(child.folderKeyEncrypted),
478	              this.internalVaultKeypair.privateKey
479	            );
480	            const ipnsPrivateKey = await unwrapKey(
481	              hexToBytes(child.ipnsPrivateKeyEncrypted),
482	              this.internalVaultKeypair.privateKey
483	            );
484	            childState = await this.loadFolder(child.ipnsName, folderKey, {
485	              // Public key is derived from the private key at signing time.
486	              publicKey: new Uint8Array(0),
487	              privateKey: ipnsPrivateKey,
488	            });
489	          } catch {
490	            // A single corrupt/undecryptable sibling entry must not abort the
491	            // whole bootstrap — skip it so unrelated targets stay reachable.
492	            // (Generic catch: unwrapKey/hexToBytes throw key-free errors.)
493	            continue;
494	          }
495	        }
496	        // Could not resolve this subfolder (no IPNS record) — skip it.
497	        if (!childState) continue;
498	        if (child.ipnsName === targetIpnsName) return childState;
499	        stack.push(childState);
