export const meta = {
  name: 'rootcause-web-e2e-phase48',
  description: 'Root-cause 2 web-e2e regressions (invite-link + writable-shares) from Phase 48 share changes',
  phases: [
    { title: 'Gather', detail: 'parallel: CI artifacts/screenshots, both specs, REQ-4 diff, REQ-3 diff, duplicate-key DB angle' },
    { title: 'Synthesize', detail: 'adversarially confirm a root cause + precise fix per failure against source' },
  ],
}

const RUN_ID = '27627456346'

const GATHER_SCHEMA = {
  type: 'object',
  additionalProperties: false,
  required: ['summary', 'findings', 'decisive_evidence'],
  properties: {
    summary: { type: 'string', description: 'One-paragraph summary of what you found' },
    findings: {
      type: 'array',
      items: {
        type: 'object',
        additionalProperties: false,
        required: ['claim', 'evidence', 'file_or_source'],
        properties: {
          claim: { type: 'string' },
          evidence: { type: 'string', description: 'concrete: file:line, log line, screenshot description, code snippet' },
          file_or_source: { type: 'string' },
        },
      },
    },
    decisive_evidence: { type: 'string', description: 'The single most decisive piece of evidence about WHY the test hangs/fails' },
  },
}

const SYNTH_SCHEMA = {
  type: 'object',
  additionalProperties: false,
  required: ['failure', 'root_cause', 'confidence', 'introduced_by', 'fix', 'fix_files', 'fix_risk', 'alternative_if_wrong'],
  properties: {
    failure: { type: 'string' },
    root_cause: { type: 'string', description: 'Precise mechanism: what code change causes the test to hang/fail, traced end-to-end' },
    confidence: { type: 'string', enum: ['high', 'medium', 'low'] },
    introduced_by: { type: 'string', description: 'Which commit/plan (48-02/03/04/05/06/07) introduced it, with the specific change' },
    fix: { type: 'string', description: 'Exact code change to make, with before/after where possible' },
    fix_files: { type: 'array', items: { type: 'string' } },
    fix_risk: { type: 'string', description: 'Blast radius + what else could break + how to verify' },
    alternative_if_wrong: { type: 'string', description: 'If this root cause is wrong, the next most likely cause to check' },
  },
}

phase('Gather')

const gather = await parallel([
  // 1. CI artifacts + failure screenshots (ground truth runtime state)
  () => agent(
    `Root-cause investigation for a failing Playwright web-e2e run. Download the CI artifacts for GitHub Actions run ${RUN_ID} (repo FSM1/cipher-box) and inspect the FAILURE SCREENSHOTS + any error-context for these two failing tests:
  A) tests/invite-link-workflow.spec.ts:280 "3.1 Alice creates an invite link for a file" — times out at spec line 294 calling a page-object waitForSuccess() (page object line 96).
  B) tests/writable-shares.spec.ts:844 "10.3 Bob opens the write-shared file and can edit it" — times out at spec line 873: await textEditor.waitFor({ state: 'hidden', timeout: 30000 }).

STEPS:
- cd /Users/myankelev/Code/random/cipher-box
- mkdir -p /tmp/wf-e2e-artifacts && env -u GITHUB_TOKEN gh run download ${RUN_ID} --dir /tmp/wf-e2e-artifacts 2>&1 | tail -5  (if it fails, list artifacts with: env -u GITHUB_TOKEN gh api repos/FSM1/cipher-box/actions/runs/${RUN_ID}/artifacts --jq '.artifacts[].name' and download the playwright report artifact by name).
- find /tmp/wf-e2e-artifacts -type d -iname '*invite-link*' and '*writable-shares*' to locate the per-test test-results folders. They contain test-failed-*.png screenshots and possibly error-context.md / *.txt.
- Use the Read tool (vision) to LOOK at each test-failed PNG for BOTH tests. Describe precisely what is on screen at the moment of failure: any error toast/banner, a stuck loading spinner, an open dialog/editor, an error message string, the breadcrumb/route, whether the expected success UI is present or absent.
- Grep any error-context.md or trace text for console errors, uncaught exceptions, HTTP 4xx/5xx, and stack traces relevant to each test.

Report what the UI actually shows at failure for EACH test and the decisive runtime error if any. Be concrete (filenames, exact on-screen text). Return ONLY via the structured schema.`,
    { label: 'gather:artifacts+screenshots', phase: 'Gather', schema: GATHER_SCHEMA, agentType: 'general-purpose' }
  ),

  // 2. invite-link spec + page objects
  () => agent(
    `Read these files in /Users/myankelev/Code/random/cipher-box and explain EXACTLY what the failing assertion requires:
- tests/web-e2e/tests/invite-link-workflow.spec.ts lines 240-310 (the "3.1 Alice creates an invite link for a file" test; it times out at line 294).
- The page object whose waitForSuccess() is at line ~96 (find it: grep -rn 'async waitForSuccess' tests/web-e2e/page-objects). Read that method and what locator/state it waits for, and what user action (button click / form submit) precedes it in the test.
- Trace what UI flow "create an invite LINK for a file" triggers in the web app: which dialog/component, which API call (create-invite or create-share), and whether a LINK invite (claimed by anyone later) differs from a direct user-to-user invite (specific recipient public key).

Goal: pin down what on-screen success state never appears, and what the create-link flow calls. Return ONLY via the structured schema.`,
    { label: 'gather:spec-invite', phase: 'Gather', schema: GATHER_SCHEMA, agentType: 'general-purpose' }
  ),

  // 3. writable-shares spec + editor/save page objects
  () => agent(
    `Read these files in /Users/myankelev/Code/random/cipher-box and explain EXACTLY what the failing assertion requires:
- tests/web-e2e/tests/writable-shares.spec.ts lines 800-900 (the "10.3 Bob opens the write-shared file and can edit it" test; it times out at line 873: await textEditor.waitFor({ state: 'hidden', timeout: 30000 })).
- The page objects for opening a shared file, editing in the text editor, and SAVING/closing it (grep tests/web-e2e/page-objects for the text-editor + save flow). What action is supposed to make the editor become hidden (a Save that succeeds and closes the editor)?
- Trace the web flow for "Bob (recipient) edits a write-shared file and saves": which hook/component handles the save, and which SDK client method it calls (updateSharedFile / uploadToSharedFolder). 

Goal: identify what must succeed for the editor to hide, i.e. the shared-file SAVE path. If the save throws/hangs, the editor stays open and the test times out. Return ONLY via the structured schema.`,
    { label: 'gather:spec-writable', phase: 'Gather', schema: GATHER_SCHEMA, agentType: 'general-purpose' }
  ),

  // 4. REQ-4 diff (itemName encryption) — link-invite-no-recipient hypothesis
  () => agent(
    `Investigate whether Phase 48 REQ-4 (encrypt share itemName at rest) broke INVITE LINK creation. In /Users/myankelev/Code/random/cipher-box:
- Read the REQ-4 web impl diff: git show e1589c0d3 (feat: ECIES-wrap share itemName on create and decrypt for display). Also git show b05694532 (API: item_name_encrypted column + DTOs).
- KEY HYPOTHESIS to confirm or refute: itemName is ECIES-wrapped with the RECIPIENT's public key (mirroring encryptedKey). A direct user-to-user invite HAS a recipient public key, but an invite LINK is claimed by an arbitrary user LATER — at link-creation time there may be NO recipient public key. If the new code unconditionally wraps itemName with a recipient pubkey on the link-invite path, it will throw / send nothing / hang the create flow.
- Find the share/invite creation component(s) (grep web src for ShareDialog, create-invite, createInviteLink, itemNameEncrypted, wrapKey). Determine: does the link-invite creation path try to wrap itemName, and with what key? Does it differ from how encryptedKey is handled for link invites (link invites typically use a link secret, not a recipient pubkey)?
- Check the API create-invite.dto.ts / create-share.dto.ts: is itemNameEncrypted required or optional? Would a missing/invalid value cause a 400 that hangs the UI?

Report whether the link-invite path is broken by REQ-4 and exactly where. Return ONLY via the structured schema.`,
    { label: 'gather:diff-req4', phase: 'Gather', schema: GATHER_SCHEMA, agentType: 'general-purpose' }
  ),

  // 5. REQ-3 diff (shared write routing) — editor-never-hides hypothesis
  () => agent(
    `Investigate whether Phase 48 REQ-3 (route shared-folder writes through the SDK) broke the recipient SHARED-FILE SAVE/edit flow. In /Users/myankelev/Code/random/cipher-box:
- Read these diffs: git show 0949e1f43 (48-04: route shared-folder writes through SDK with event-fed projection), git show 20413f863 (48-07: route shared poller through SDK refreshSharedFolder), git show c95dc9840 (48-07: SDK client.refreshSharedFolder), git show 64e8b8967 (48-03: SDK client owns shared-folder state and publish).
- Read apps/web/src/hooks/useSharedWriteOps.ts, apps/web/src/hooks/useSharedNavigation.ts, apps/web/src/hooks/shared-folder-projection.ts, and the SDK client shared methods in packages/sdk/src/client.ts (updateSharedFile / uploadToSharedFolder / refreshSharedFolder / adoptSharedFolderResult).
- KEY QUESTION: when Bob (recipient) edits a write-shared FILE and saves, which path runs? Does the save now route through a client method that reads nothing back (per the 48-04 projection design)? Could it throw 'Shared folder not loaded' (requireSharedFolder) because the shared folder/file context isn't seeded after opening the file? Could the 48-07 poller's refreshSharedFolder now clobber or race the in-flight save? Could the projection subscription never emit, so the UI never learns the save completed and the editor never closes?
- Note: the test opens a write-shared FILE (not just a folder). Check whether opening a shared file seeds the sharedFolderTree the write path requires.

Report the most likely reason the editor never hides after a recipient save, with file:line evidence. Return ONLY via the structured schema.`,
    { label: 'gather:diff-req3', phase: 'Gather', schema: GATHER_SCHEMA, agentType: 'general-purpose' }
  ),

  // 6. duplicate-key UQ_folder_ipns_user_ipns angle (REQ-2 self-bootstrap double-register)
  () => agent(
    `Investigate a DB error seen during the failing run: "duplicate key value violates unique constraint UQ_folder_ipns_user_ipns" (an INSERT INTO folder_ipns collision on user_id + ipns_name). It appears around the invite-link-creation failure. In /Users/myankelev/Code/random/cipher-box:
- Find the folder_ipns unique constraint + the register/publish path that INSERTs it (grep api src for UQ_folder_ipns_user_ipns, folder_ipns, registerFolder, publishFolder; grep sdk for folder registration / self-bootstrap).
- Read the REQ-2 diff: git show df1223bf3 (refactor: remove web folder-seeding now that SDK self-bootstraps) and recall PR #498 self-bootstrap registers the folder tree from the root IPNS key.
- HYPOTHESIS: with web folder-seeding removed, the SDK self-bootstrap now (re)registers folder IPNS records that already exist server-side, causing a duplicate-key INSERT instead of an idempotent upsert — during share/invite creation. Confirm whether the registration path is INSERT (not upsert/ON CONFLICT) and whether the self-bootstrap or share-create flow can register an already-registered folder.
- Determine if this duplicate-key error would actually BLOCK invite-link creation (i.e. is it on the critical path of the failing test) or is it benign background noise.

Report whether the duplicate-key is causal for the invite-link failure and where the non-idempotent register is. Return ONLY via the structured schema.`,
    { label: 'gather:duplicate-key', phase: 'Gather', schema: GATHER_SCHEMA, agentType: 'general-purpose' }
  ),
])

const g = gather.filter(Boolean)
const gatherBlob = g.map((r, i) => `### Gather source ${i + 1}\nSummary: ${r.summary}\nDecisive: ${r.decisive_evidence}\nFindings:\n${(r.findings || []).map(f => `- ${f.claim} | ${f.evidence} | ${f.file_or_source}`).join('\n')}`).join('\n\n')

phase('Synthesize')

const synth = await parallel([
  () => agent(
    `You are root-causing a SINGLE failing web-e2e test. Use the gathered evidence below + read the actual source to ADVERSARIALLY confirm a precise root cause and a minimal fix. Do not accept a hypothesis you cannot verify in the code — open the files and check.

FAILING TEST: tests/invite-link-workflow.spec.ts:280 "3.1 Alice creates an invite link for a file" — times out at line 294 (page-object waitForSuccess never resolves). A "duplicate key UQ_folder_ipns_user_ipns" DB error appears in the same window.

GATHERED EVIDENCE:
${gatherBlob}

Read whatever source you need under /Users/myankelev/Code/random/cipher-box (web invite-link/share-create component, SDK self-bootstrap/folder register, API create-invite). Determine the EXACT mechanism that prevents the invite-link success UI from appearing, name the introducing commit/plan, and give a minimal, surgical fix with file:line. If two causes interact (e.g. duplicate-key AND itemName wrap), say which is on the critical path. Return ONLY via the structured schema.`,
    { label: 'synth:invite-link', phase: 'Synthesize', schema: SYNTH_SCHEMA, agentType: 'general-purpose' }
  ),
  () => agent(
    `You are root-causing a SINGLE failing web-e2e test. Use the gathered evidence below + read the actual source to ADVERSARIALLY confirm a precise root cause and a minimal fix. Do not accept a hypothesis you cannot verify in the code — open the files and check.

FAILING TEST: tests/writable-shares.spec.ts:844 "10.3 Bob opens the write-shared file and can edit it" — times out at line 873: await textEditor.waitFor({ state: 'hidden', timeout: 30000 }) (the editor never closes after Bob saves his edit to a write-shared file).

GATHERED EVIDENCE:
${gatherBlob}

Read whatever source you need under /Users/myankelev/Code/random/cipher-box (apps/web/src/hooks/useSharedWriteOps.ts, useSharedNavigation.ts, shared-folder-projection.ts, the editor/save component, packages/sdk/src/client.ts shared methods). Determine the EXACT mechanism that keeps the editor open after a recipient save (save throws? requireSharedFolder 'Shared folder not loaded'? projection never emits so UI never closes? poller race?), name the introducing commit/plan, and give a minimal, surgical fix with file:line. Return ONLY via the structured schema.`,
    { label: 'synth:writable-shares', phase: 'Synthesize', schema: SYNTH_SCHEMA, agentType: 'general-purpose' }
  ),
])

return { gather: g, synthesis: synth.filter(Boolean) }

