28	import type { SharedListItem, SharedBreadcrumb } from './useSharedNavigation';
29	
30	type NavStackEntry = {
31	  folderId: string;
32	  folderName: string;
33	  children: FolderChild[];
34	  folderKey: Uint8Array;
35	  ipnsName: string;
36	  sequenceNumber: bigint | null;
37	};
