39	export type SharedNavigationActionsParams = {
40	  sharedItems: SharedListItem[];
41	  folderChildren: FolderChild[];
42	  folderKey: Uint8Array | null;
43	  breadcrumbs: SharedBreadcrumb[];
44	  currentShareId: string | null;
45	  permission: 'read' | 'write' | null;
46	  ipnsName: string | null;
47	  currentSequenceNumber: bigint | null;
48	  currentView: 'list' | 'folder' | 'file';
49	  // Refs
50	  folderChildrenRef: MutableRefObject<FolderChild[]>;
51	  sequenceNumberRef: MutableRefObject<bigint | null>;
52	  ipnsPrivateKeyRef: MutableRefObject<Uint8Array | null>;
53	  navStackRef: MutableRefObject<NavStackEntry[]>;
54	  shareKeysCacheRef: MutableRefObject<ShareKeyCache>;
55	  // State setters
56	  setCurrentView: (view: 'list' | 'folder' | 'file') => void;
57	  setCurrentShareId: (id: string | null) => void;
58	  setFolderChildren: (children: FolderChild[]) => void;
59	  setFolderKey: (key: Uint8Array | null) => void;
60	  setBreadcrumbs: (
61	    crumbs: SharedBreadcrumb[] | ((prev: SharedBreadcrumb[]) => SharedBreadcrumb[])
62	  ) => void;
63	  setPermission: (perm: 'read' | 'write' | null) => void;
64	  setIpnsName: (name: string | null) => void;
65	  setCurrentSequenceNumber: (seq: bigint | null) => void;
66	  setIsLoading: (loading: boolean) => void;
67	  setError: (error: string | null) => void;
68	  setSharedItems: (updater: (prev: SharedListItem[]) => SharedListItem[]) => void;
69	  // Helpers from orchestrator
70	  clearPolling: () => void;
71	  zeroIpnsKey: () => void;
72	  getShareKeys: (
73	    shareId: string
74	  ) => Promise<Array<{ keyType: string; itemId: string; encryptedKey: string }>>;
75	  /**
76	   * Seed (or re-seed) the SDK's sharedFolderTree for the active depth. Called on
77	   * every navigation that changes the active folder context so the SDK stays the
78	   * single source of truth for shared write state (REQ-3).
79	   */
80	  seedActiveSharedFolder: (args: Omit<SeedSharedFolderArgs, 'addShareKeysFn'>) => void;
81	};
