83	export function useSharedNavigationActions(p: SharedNavigationActionsParams) {
84	  /**
85	   * Navigate into a shared folder/file from the top-level list.
86	   */
87	  const navigateToShare = useCallback(
88	    async (shareId: string) => {
89	      const auth = useAuthStore.getState();
90	      if (!auth.vaultKeypair) {
91	        p.setError('No keypair available');
92	        return;
93	      }
94	
95	      const shareItem = p.sharedItems.find((s) => s.share.shareId === shareId);
96	      if (!shareItem) return;
97	
98	      const share = shareItem.share;
99	
100	      p.setIsLoading(true);
101	      p.setError(null);
102	      p.clearPolling();
103	
104	      try {
105	        const itemKey = await unwrapKey(
106	          hexToBytes(share.encryptedKey),
107	          auth.vaultKeypair.privateKey
108	        );
109	
110	        if (share.itemType === 'folder') {
111	          let folderKeyStored = false;
112	          try {
113	            const resolved = await resolveIpnsRecord(share.ipnsName);
114	            if (!resolved) throw new Error('Could not resolve shared folder IPNS');
115	
116	            const encryptedBytes = await fetchFromIpfs(resolved.cid);
117	            const encryptedJson = new TextDecoder().decode(encryptedBytes);
118	            const encrypted: EncryptedFolderMetadata = JSON.parse(encryptedJson);
119	            const metadata = await decryptFolderMetadata(encrypted, itemKey);
120	
121	            if (share.permission === 'write' && share.encryptedIpnsKey) {
122	              try {
123	                const ipnsPrivKey = await unwrapKey(
124	                  hexToBytes(share.encryptedIpnsKey),
125	                  auth.vaultKeypair.privateKey
126	                );
127	                p.ipnsPrivateKeyRef.current = ipnsPrivKey;
128	              } catch (err) {
129	                logger.error('[SharedNav] Failed to unwrap IPNS key for write share:', err);
130	              }
131	            }
132	
133	            const children = metadata.children ?? [];
134	            const seqNum = BigInt(resolved.sequenceNumber);
135	            p.setCurrentView('folder');
136	            p.setCurrentShareId(shareId);
137	            p.setFolderChildren(children);
138	            p.folderChildrenRef.current = children;
139	            p.setFolderKey(itemKey);
140	            folderKeyStored = true;
141	            p.setBreadcrumbs([{ id: shareId, name: share.itemName }]);
142	            p.setPermission(p.ipnsPrivateKeyRef.current ? share.permission : 'read');
143	            p.setIpnsName(share.ipnsName);
144	            p.setCurrentSequenceNumber(seqNum);
145	            p.sequenceNumberRef.current = seqNum;
146	            p.navStackRef.current = [];
147	
148	            // Seed the SDK as the single owner of shared write state for this
149	            // depth (REQ-3). Only write shares (IPNS key present) can mutate.
150	            if (p.ipnsPrivateKeyRef.current && auth.vaultKeypair) {
151	              p.seedActiveSharedFolder({
152	                shareId,
153	                ipnsName: share.ipnsName,
154	                folderKey: itemKey,
155	                ipnsPrivateKey: p.ipnsPrivateKeyRef.current,
156	                sequenceNumber: seqNum,
157	                children,
158	                ownerPublicKey: parsePublicKey(share.sharerPublicKey),
159	                recipientPublicKey: auth.vaultKeypair.publicKey,
160	              });
161	            }
162	          } finally {
163	            if (!folderKeyStored) itemKey.fill(0);
164	          }
165	        } else {
166	          let folderKeyStored = false;
167	          try {
168	            if (share.permission === 'write' && share.encryptedIpnsKey) {
169	              try {
170	                const ipnsPrivKey = await unwrapKey(
171	                  hexToBytes(share.encryptedIpnsKey),
172	                  auth.vaultKeypair.privateKey
173	                );
174	                p.ipnsPrivateKeyRef.current = ipnsPrivKey;
175	              } catch (err) {
176	                logger.error('[SharedNav] Failed to unwrap IPNS key for write file share:', err);
177	              }
178	            }
179	            p.setCurrentView('file');
180	            p.setCurrentShareId(shareId);
181	            p.setFolderKey(itemKey);
182	            folderKeyStored = true;
183	            p.setPermission(p.ipnsPrivateKeyRef.current ? share.permission : 'read');
184	            p.setIpnsName(share.ipnsName);
185	            p.setBreadcrumbs([{ id: shareId, name: share.itemName }]);
186	          } finally {
187	            if (!folderKeyStored) itemKey.fill(0);
188	          }
189	        }
190	      } catch (err) {
191	        logger.error('[SharedNav] Failed to navigate to shared item:', err);
192	        p.setError('Failed to open shared item');
193	      } finally {
194	        p.setIsLoading(false);
195	      }
196	    },
197	    [p.sharedItems, p.clearPolling]
198	  );
199	
200	  /**
201	   * Navigate into a subfolder within a shared folder.
202	   */
203	  const navigateToSubfolder = useCallback(
204	    async (folderId: string, folderName: string) => {
205	      const auth = useAuthStore.getState();
206	      if (!auth.vaultKeypair || !p.currentShareId) return;
207	
208	      p.setIsLoading(true);
209	      p.setError(null);
210	      p.clearPolling();
211	
212	      try {
213	        const keys = await p.getShareKeys(p.currentShareId);
214	        const keyRecord = keys.find((k) => k.keyType === 'folder' && k.itemId === folderId);
215	        if (!keyRecord) throw new Error('No key available for this subfolder');
216	
217	        const subfolderKey = await unwrapKey(
218	          hexToBytes(keyRecord.encryptedKey),
219	          auth.vaultKeypair.privateKey
220	        );
221	        let subfolderKeyStored = false;
222	
223	        try {
224	          const folderEntry = p.folderChildren.find(
225	            (c): c is FolderEntry => c.type === 'folder' && c.id === folderId
226	          );
227	          if (!folderEntry) throw new Error('Subfolder not found in current children');
228	
229	          const resolved = await resolveIpnsRecord(folderEntry.ipnsName);
230	          if (!resolved) throw new Error('Could not resolve subfolder IPNS');
231	
232	          const encryptedBytes = await fetchFromIpfs(resolved.cid);
233	          const encryptedJson = new TextDecoder().decode(encryptedBytes);
234	          const encrypted: EncryptedFolderMetadata = JSON.parse(encryptedJson);
235	          const metadata = await decryptFolderMetadata(encrypted, subfolderKey);
236	
237	          if (p.folderKey && p.ipnsName) {
238	            p.navStackRef.current.push({
239	              folderId: p.breadcrumbs[p.breadcrumbs.length - 1]?.id ?? '',
240	              folderName: p.breadcrumbs[p.breadcrumbs.length - 1]?.name ?? '',
241	              children: p.folderChildren,
242	              folderKey: p.folderKey,
243	              ipnsName: p.ipnsName,
244	              sequenceNumber: p.currentSequenceNumber,
245	            });
246	          }
247	
248	          const children = metadata.children ?? [];
249	          const seqNum = BigInt(resolved.sequenceNumber);
250	          p.setFolderChildren(children);
251	          p.folderChildrenRef.current = children;
252	          p.setFolderKey(subfolderKey);
253	          subfolderKeyStored = true;
254	          p.setBreadcrumbs((prev) => [...prev, { id: folderId, name: folderName }]);
255	          p.setIpnsName(folderEntry.ipnsName);
256	          p.setCurrentSequenceNumber(seqNum);
257	          p.sequenceNumberRef.current = seqNum;
258	
259	          if (p.permission === 'write' && p.currentShareId) {
260	            p.zeroIpnsKey();
261	            let restored = false;
262	            try {
263	              const subKeys = await p.getShareKeys(p.currentShareId);
264	              const ipnsKeyRecord = subKeys.find(
265	                (k) => k.keyType === 'folder-ipns' && k.itemId === folderId
266	              );
267	              if (ipnsKeyRecord) {
268	                const ipnsPrivKey = await unwrapKey(
269	                  hexToBytes(ipnsKeyRecord.encryptedKey),
270	                  auth.vaultKeypair.privateKey
271	                );
272	                p.ipnsPrivateKeyRef.current = ipnsPrivKey;
273	                restored = true;
274	              }
275	            } catch {
276	              // Couldn't get subfolder IPNS key
277	            }
278	            if (!restored) p.setPermission('read');
279	
280	            // Re-seed the SDK for this subfolder depth (distinct ipnsName /
281	            // folderKey / IPNS key / sequence under the same shareId).
282	            if (restored && p.ipnsPrivateKeyRef.current) {
283	              const ownerShare = p.sharedItems.find(
284	                (s) => s.share.shareId === p.currentShareId
285	              )?.share;
286	              if (ownerShare) {
287	                p.seedActiveSharedFolder({
288	                  shareId: p.currentShareId,
289	                  ipnsName: folderEntry.ipnsName,
290	                  folderKey: subfolderKey,
291	                  ipnsPrivateKey: p.ipnsPrivateKeyRef.current,
292	                  sequenceNumber: seqNum,
293	                  children,
294	                  ownerPublicKey: parsePublicKey(ownerShare.sharerPublicKey),
295	                  recipientPublicKey: auth.vaultKeypair.publicKey,
296	                });
297	              }
298	            }
299	          }
300	        } finally {
301	          if (!subfolderKeyStored) subfolderKey.fill(0);
302	        }
303	      } catch (err) {
304	        logger.error('[SharedNav] Failed to navigate to subfolder:', err);
305	        p.setError('Failed to open subfolder');
306	      } finally {
307	        p.setIsLoading(false);
308	      }
309	    },
310	    [
311	      p.currentShareId,
312	      p.folderChildren,
313	      p.folderKey,
314	      p.breadcrumbs,
315	      p.getShareKeys,
316	      p.ipnsName,
317	      p.currentSequenceNumber,
318	      p.clearPolling,
319	      p.permission,
320	      p.zeroIpnsKey,
321	    ]
322	  );
323	
324	  /**
325	   * Navigate back to the top-level shared list.
326	   */
327	  const navigateToRoot = useCallback(() => {
328	    if (p.folderKey) p.folderKey.fill(0);
329	    for (const entry of p.navStackRef.current) {
330	      entry.folderKey.fill(0);
331	    }
332	    p.zeroIpnsKey();
333	    p.clearPolling();
334	    p.setCurrentView('list');
335	    p.setCurrentShareId(null);
336	    p.setFolderChildren([]);
337	    p.setFolderKey(null);
338	    p.setBreadcrumbs([]);
339	    p.setPermission(null);
340	    p.setIpnsName(null);
341	    p.setCurrentSequenceNumber(null);
342	    p.navStackRef.current = [];
343	    p.setError(null);
344	  }, [p.folderKey, p.zeroIpnsKey, p.clearPolling]);
345	
346	  /**
347	   * Re-seed the SDK's sharedFolderTree for a restored (up / breadcrumb) depth,
348	   * once the IPNS key for that depth has been restored. `depth` carries the
349	   * folderKey / ipnsName / children / sequence of the level we navigated back
350	   * to; the IPNS key + owner/recipient pubkeys come from the active share.
351	   */
352	  const reseedRestoredDepth = useCallback(
353	    (depth: {
354	      folderKey: Uint8Array;
355	      ipnsName: string;
356	      children: FolderChild[];
357	      sequenceNumber: bigint | null;
358	    }) => {
359	      if (!p.currentShareId || !p.ipnsPrivateKeyRef.current) return;
360	      const auth = useAuthStore.getState();
361	      if (!auth.vaultKeypair) return;
362	      const share = p.sharedItems.find((s) => s.share.shareId === p.currentShareId)?.share;
363	      if (!share) return;
364	      p.seedActiveSharedFolder({
365	        shareId: p.currentShareId,
366	        ipnsName: depth.ipnsName,
367	        folderKey: depth.folderKey,
368	        ipnsPrivateKey: p.ipnsPrivateKeyRef.current,
369	        sequenceNumber: depth.sequenceNumber ?? 0n,
370	        children: depth.children,
371	        ownerPublicKey: parsePublicKey(share.sharerPublicKey),
372	        recipientPublicKey: auth.vaultKeypair.publicKey,
373	      });
374	    },
375	    [p.currentShareId, p.sharedItems]
376	  );
377	
378	  /**
379	   * Restore the correct IPNS private key for the current depth.
380	   */
381	  const restoreIpnsKeyForDepth = useCallback(
382	    async (targetFolderId?: string) => {
383	      if (!p.currentShareId) return;
384	      const shareItem = p.sharedItems.find((s) => s.share.shareId === p.currentShareId);
385	      const share = shareItem?.share;
386	      if (share?.permission !== 'write') return;
387	
388	      p.zeroIpnsKey();
389	      const auth = useAuthStore.getState();
390	      if (!auth.vaultKeypair) return;
391	
392	      try {
393	        if (!targetFolderId && share.encryptedIpnsKey) {
394	          const ipnsPrivKey = await unwrapKey(
395	            hexToBytes(share.encryptedIpnsKey),
396	            auth.vaultKeypair.privateKey
397	          );
398	          p.ipnsPrivateKeyRef.current = ipnsPrivKey;
399	          p.setPermission('write');
400	        } else if (targetFolderId) {
401	          const keys = await p.getShareKeys(p.currentShareId);
402	          const ipnsKeyRecord = keys.find(
403	            (k) => k.keyType === 'folder-ipns' && k.itemId === targetFolderId
404	          );
405	          if (ipnsKeyRecord) {
406	            const ipnsPrivKey = await unwrapKey(
407	              hexToBytes(ipnsKeyRecord.encryptedKey),
408	              auth.vaultKeypair.privateKey
409	            );
410	            p.ipnsPrivateKeyRef.current = ipnsPrivKey;
411	            p.setPermission('write');
412	          } else {
413	            p.setPermission('read');
414	          }
415	        }
416	      } catch {
417	        // Couldn't restore — stay read-only
418	      }
419	    },
420	    [p.currentShareId, p.getShareKeys, p.sharedItems, p.zeroIpnsKey]
421	  );
422	
423	  /**
424	   * Navigate up one level.
425	   */
426	  const navigateUp = useCallback(async () => {
427	    if (p.navStackRef.current.length > 0) {
428	      if (p.folderKey) p.folderKey.fill(0);
429	      const prev = p.navStackRef.current.pop()!;
430	      p.setFolderChildren(prev.children);
431	      p.folderChildrenRef.current = prev.children;
432	      p.setFolderKey(prev.folderKey);
433	      p.setBreadcrumbs((crumbs) => crumbs.slice(0, -1));
434	      p.setIpnsName(prev.ipnsName);
435	      p.setCurrentSequenceNumber(prev.sequenceNumber);
436	      p.sequenceNumberRef.current = prev.sequenceNumber;
437	
438	      if (p.navStackRef.current.length === 0) {
439	        await restoreIpnsKeyForDepth();
440	      } else {
441	        await restoreIpnsKeyForDepth(prev.folderId);
442	      }
443	      reseedRestoredDepth(prev);
444	    } else if (p.currentView === 'folder' || p.currentView === 'file') {
445	      navigateToRoot();
446	    }
447	  }, [p.currentView, p.folderKey, navigateToRoot, restoreIpnsKeyForDepth, reseedRestoredDepth]);
448	
449	  /**
450	   * Navigate directly to a breadcrumb level.
451	   */
452	  const navigateToBreadcrumb = useCallback(
453	    async (crumbIndex: number) => {
454	      const popsNeeded = p.breadcrumbs.length - 1 - crumbIndex;
455	      if (popsNeeded <= 0) return;
456	      if (p.folderKey) p.folderKey.fill(0);
457	      for (let i = 0; i < popsNeeded - 1; i++) {
458	        const entry = p.navStackRef.current.pop();
459	        if (entry) entry.folderKey.fill(0);
460	      }
461	      const target = p.navStackRef.current.pop();
462	      if (target) {
463	        p.setFolderChildren(target.children);
464	        p.folderChildrenRef.current = target.children;
465	        p.setFolderKey(target.folderKey);
466	        p.setBreadcrumbs((crumbs) => crumbs.slice(0, crumbIndex + 1));
467	        p.setIpnsName(target.ipnsName);
468	        p.setCurrentSequenceNumber(target.sequenceNumber);
469	        p.sequenceNumberRef.current = target.sequenceNumber;
470	
471	        if (p.navStackRef.current.length === 0) {
472	          await restoreIpnsKeyForDepth();
473	        } else {
474	          await restoreIpnsKeyForDepth(target.folderId);
475	        }
476	        reseedRestoredDepth(target);
477	      }
478	    },
479	    [p.breadcrumbs, p.folderKey, restoreIpnsKeyForDepth, reseedRestoredDepth]
480	  );
481	
482	  /**
483	   * Download a shared file using re-wrapped file keys.
484	   */
485	  const downloadSharedFile = useCallback(
486	    async (item: FilePointer) => {
487	      const auth = useAuthStore.getState();
488	      if (!auth.vaultKeypair || !p.currentShareId || !p.folderKey) return;
489	
490	      const downloadStore = useDownloadStore.getState();
491	
492	      try {
493	        downloadStore.startDownload(item.name);
494	
495	        const keys = await p.getShareKeys(p.currentShareId);
496	
497	        const resolved = await resolveIpnsRecord(item.fileMetaIpnsName);
498	        if (!resolved) throw new Error('File metadata IPNS not found');
499	
500	        const encryptedBytes = await fetchFromIpfs(resolved.cid);
501	        const encryptedJson = new TextDecoder().decode(encryptedBytes);
502	        const encrypted: EncryptedFileMetadata = JSON.parse(encryptedJson);
503	        const fileMeta = await decryptFileMetadata(encrypted, p.folderKey);
504	
505	        const fileKeyRecord = keys.find((k) => k.keyType === 'file' && k.itemId === item.id);
506	        if (!fileKeyRecord) {
507	          throw new Error('File key not available — the folder owner may need to re-share');
508	        }
509	        const wrappedKey = fileKeyRecord.encryptedKey;
510	
511	        const plaintext = await downloadFile(
512	          {
513	            cid: fileMeta.cid,
514	            iv: fileMeta.fileIv,
515	            wrappedKey,
516	            originalName: item.name,
517	            encryptionMode: fileMeta.encryptionMode,
518	          },
519	          auth.vaultKeypair.privateKey
520	        );
521	
522	        downloadStore.setDecrypting();
523	        triggerBrowserDownload(plaintext, item.name);
524	        downloadStore.setSuccess();
525	      } catch (err) {
526	        const message = (err as Error).message || 'Download failed';
527	        downloadStore.setError(message);
528	        logger.error('[SharedNav] Shared file download failed:', err);
529	      }
530	    },
531	    [p.currentShareId, p.folderKey, p.getShareKeys]
532	  );
533	
534	  /**
535	   * Hide a shared item from the user's view.
536	   */
537	  const hideSharedItem = useCallback(
538	    async (shareId: string) => {
539	      try {
540	        await hideShare(shareId);
541	        useShareStore.getState().removeReceivedShare(shareId);
542	        p.setSharedItems((prev) => prev.filter((s) => s.share.shareId !== shareId));
543	      } catch (err) {
544	        logger.error('[SharedNav] Failed to hide share:', err);
545	        p.setError('Failed to hide shared item');
546	      }
547	    },
548	    [p.setSharedItems, p.setError]
549	  );
550	
551	  return {
552	    navigateToShare,
553	    navigateToSubfolder,
554	    navigateUp,
555	    navigateToRoot,
556	    navigateToBreadcrumb,
557	    downloadSharedFile,
558	    hideSharedItem,
559	  };
560	}
