1998	  private requireSharedFolder(shareId: string): SharedFolderState {
1999	    const state = this.sharedFolderTree.get(shareId);
2000	    if (!state) throw new Error('Shared folder not loaded');
2001	    return state;
2002	  }
2003	
2004	  /**
2005	   * Build a SharedWriteContext from the current shared-folder state.
2006	   * The state's per-share owner/recipient pubkeys, IPNS key, and addShareKeys
2007	   * callback are carried into the context — no cross-share bleed (T-48-07).
2008	   */
2009	  private buildSharedWriteContextFromState(
2010	    state: SharedFolderState
2011	  ): ReturnType<typeof shareOps.buildSharedWriteContext> {
2012	    return shareOps.buildSharedWriteContext({
2013	      ctx: this.ctx,
2014	      folderKey: state.folderKey,
