2016	      ipnsName: state.ipnsName,
2017	      sequenceNumber: state.sequenceNumber,
2018	      children: state.children,
2019	      ownerPublicKey: state.ownerPublicKey,
2020	      recipientPublicKey: state.recipientPublicKey,
2021	      shareId: state.shareId,
2022	      addShareKeysFn: state.addShareKeysFn,
2023	    });
2024	  }
