2026	  /**
2027	   * Adopt a shared-write result into `sharedFolderTree` and emit
2028	   * `sharedFolder:updated`. Centralizes the write-back + emission so all five
2029	   * methods stay consistent.
2030	   */
2031	  private adoptSharedFolderResult(
2032	    state: SharedFolderState,
2033	    result: { publishedChildren: FolderChild[]; newSequenceNumber: bigint }
2034	  ): void {
2035	    const next: SharedFolderState = {
2036	      ...state,
2037	      children: result.publishedChildren,
2038	      sequenceNumber: result.newSequenceNumber,
2039	    };
2040	    this.sharedFolderTree.set(state.shareId, next);
2041	    this.emitter.emit({
2042	      type: 'sharedFolder:updated',
2043	      shareId: state.shareId,
2044	      ipnsName: state.ipnsName,
2045	      children: result.publishedChildren,
