2076	    return this.withOperation('createSharedSubfolder', async () => {
2077	      const state = this.requireSharedFolder(shareId);
2078	      const result = await shareOps.createSharedSubfolder(
2079	        this.buildSharedWriteContextFromState(state),
2080	        args
2081	      );
2082	      this.adoptSharedFolderResult(state, result);
2083	    });
2084	  }
2085	
2086	  /**
2087	   * Rename an item in a write-shared folder (REQ-3).
2088	   */
2089	  async renameInSharedFolder(
2090	    shareId: string,
2091	    args: { itemId: string; newName: string }
2092	  ): Promise<void> {
